 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)

    for cells in objects:
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        height, width = r1 - r0 + 1, c1 - c0 + 1
        # A three-sided rectangular frame with a one-cell opening near the
        # right end of its top edge.
        if height < 3 or width < 4:
            continue
        if any(grid[r][c0] != 5 or grid[r][c1] != 5 for r in range(r0, r1 + 1)):
            continue
        if any(grid[r1][c] != 5 for c in range(c0, c1 + 1)):
            continue
        opening = c1 - 1
        if grid[r0][opening] != 0 or any(grid[r0][c] != 5 for c in range(c0, c1 + 1) if c != opening):
            continue
        if any(grid[r][c] != 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
            continue
        # Paint the interior and close the opening, then project left from it.
        for r in range(r0, r1):
            for c in range(c0 + 1, c1):
                if out[r][c] == 0:
                    out[r][c] = 2
        if r0 > 0:
            for c in range(opening + 1):
                if out[r0 - 1][c] == 0:
                    out[r0 - 1][c] = 2
    return out
